-- ===========================================================================
-- 0028_tools_dan_lisensi.sql
--
-- Dua blok terakhir yang diminta layar detail profesi:
--   Tools   -- aplikasi yang dipakai profesi ini, dikelompokkan menurut kapan
--              pengguna akan menyentuhnya
--   Lisensi -- izin praktik dan sertifikasi yang berlaku di Indonesia
--
-- ---------------------------------------------------------------------------
-- Tools
-- ---------------------------------------------------------------------------
-- Sumbernya file "Software Skills" O*NET: 31.821 baris (SOC x produk), tiap
-- produk sudah digolongkan ke salah satu dari 134 kategori software. Pola yang
-- sama dipakai lagi: kategori diterjemahkan sekali (134 kalimat), lalu tiap
-- profesi cukup menunjuk kategorinya.
--
-- Kategori dipilih per profesi berdasarkan berapa banyak produk nyata yang
-- O*NET catat untuk profesi itu, dengan bobot tambahan untuk yang ditandai
-- Hot Technology.
--
-- Yang tidak ada di O*NET adalah pengelompokan "kapan dipakai" yang diminta
-- desain. Itu ditetapkan per kategori, sekali, dan tertulis di kolom fase:
--
--   MANDIRI  Langsung dapat dipelajari -- aplikasi umum yang bisa dipelajari
--            sendiri, lewat kursus, atau bootcamp.
--   MAGANG   Saat magang / awal kerja -- sistem internal organisasi yang baru
--            ditemui setelah masuk kerja (EMR, POS, ERP kecil, CRM).
--   KERJA    Saat bekerja -- aplikasi kelas berat untuk tugas yang lebih
--            kompleks (ERP penuh, CAD/CAM, SCADA, BI, infrastruktur).
--
-- Pengolah kata dan pengolah angka selalu dimasukkan ke fase MANDIRI meski
-- O*NET tidak mencatatnya untuk profesi itu: dua aplikasi ini dipakai di
-- hampir semua pekerjaan kantor Indonesia, dan layar Skill Gap perlu isi di
-- fase pertama untuk semua profesi.
--
-- ---------------------------------------------------------------------------
-- Lisensi
-- ---------------------------------------------------------------------------
-- Tidak ada di O*NET, yang memetakan lisensi Amerika. Katalog di bawah disusun
-- dari regulasi Indonesia; tiap entri menyebut penerbitnya supaya bisa
-- diperiksa. 0007 sudah punya daftar izin praktik, tapi berupa satu kalimat
-- bebas per profesi -- desain butuh entri terpisah dengan nama, penerbit, dan
-- sifat, jadi di sini dibuat terstruktur.
--
-- Sifat dibedakan supaya aplikasi tidak menyamakan hal yang berbeda:
--   WAJIB    syarat hukum untuk boleh bekerja (STR, SIP, SKK, STRI)
--   PROFESI  sertifikat kompetensi yang lazim diminta pemberi kerja
--   TAMBAHAN menambah nilai, tidak menghalangi bekerja
--
-- Jalankan setelah 0027. Aman diulang.
-- ===========================================================================

begin;

-- ---------------------------------------------------------------------------
-- 1. Fase pemakaian tools
-- ---------------------------------------------------------------------------
create table if not exists public.tool_phases (
  code       text primary key,
  name_id    text     not null,
  subtitle   text     not null,
  sort_order smallint not null
);

insert into public.tool_phases (code, name_id, subtitle, sort_order) values
  ('MANDIRI', 'Langsung dapat dipelajari',
   'Kamu dapat mempelajari aplikasi di bawah ini baik secara mandiri, kursus, maupun jalur bootcamp.', 1),
  ('MAGANG',  'Saat Magang / Awal Kerja',
   'Tools ini biasanya mulai digunakan saat Kamu mulai magang atau bekerja.', 2),
  ('KERJA',   'Saat Bekerja',
   'Tools ini umumnya digunakan saat Kamu sudah bekerja dan menangani tugas yang lebih kompleks.', 3)
on conflict (code) do update set
  name_id = excluded.name_id, subtitle = excluded.subtitle,
  sort_order = excluded.sort_order;

alter table public.tool_phases enable row level security;
drop policy if exists tool_phases_read_all on public.tool_phases;
create policy tool_phases_read_all on public.tool_phases
  for select to anon, authenticated using (true);

-- ---------------------------------------------------------------------------
-- 2. Katalog tools
-- ---------------------------------------------------------------------------
create table if not exists public.tools (
  code        text primary key,             -- Element ID O*NET, mis. '2.E.4.i'
  name_id     text        not null,
  name_en     text        not null,
  phase_code  text        not null references public.tool_phases(code),
  description_id text     not null,
  created_at  timestamptz not null default now()
);

comment on table public.tools is
  'Kategori software O*NET (2.E.*) dalam bahasa Indonesia. phase_code ditetapkan manual, bukan dari O*NET.';

alter table public.tools enable row level security;
drop policy if exists tools_read_all on public.tools;
create policy tools_read_all on public.tools
  for select to anon, authenticated using (true);

create table if not exists public.career_tools (
  career_id     integer  not null references public.careers(id) on delete cascade,
  tool_code     text     not null references public.tools(code) on delete cascade,
  contoh_produk text,                       -- Workplace Example O*NET, mis. 'Epic Systems'
  display_order smallint not null,
  primary key (career_id, tool_code)
);

comment on column public.career_tools.contoh_produk is
  'Satu contoh produk nyata dari O*NET Workplace Example, untuk membumikan nama kategori.';

create index if not exists idx_career_tools_career
  on public.career_tools (career_id, display_order);

alter table public.career_tools enable row level security;
drop policy if exists career_tools_read_all on public.career_tools;
create policy career_tools_read_all on public.career_tools
  for select to anon, authenticated using (true);

