delete from public.career_tools;

insert into public.career_tools (career_id, tool_code, contoh_produk, display_order)
select c.id, t.tool_code, t.contoh, t.display_order
from public.careers c
left join public.career_onet_map om on om.career_id = c.id
join _soc_tool t on t.soc_code = coalesce(c.soc_code, om.soc_code)
where c.is_active
on conflict (career_id, tool_code) do nothing;

-- Profesi yang O*NET tidak catat software-nya sama sekali tetap harus punya
-- fase pertama yang terisi: layar Skill Gap menampilkan ketiga fase.
insert into public.career_tools (career_id, tool_code, contoh_produk, display_order)
select c.id, t.code, null, 1
from public.careers c
cross join lateral (values ('2.E.4.d'), ('2.E.4.i')) as t(code)
where c.is_active
  and not exists (select 1 from public.career_tools x where x.career_id = c.id)
on conflict (career_id, tool_code) do nothing;

-- ---------------------------------------------------------------------------
-- 3. Lisensi & sertifikasi
-- ---------------------------------------------------------------------------
create table if not exists public.license_issuers (
  code    text primary key,
  name_id text not null
);

alter table public.license_issuers enable row level security;
drop policy if exists license_issuers_read_all on public.license_issuers;
create policy license_issuers_read_all on public.license_issuers
  for select to anon, authenticated using (true);

create table if not exists public.licenses (
  code           text primary key,
  name_id        text not null,
  issuer_code    text not null references public.license_issuers(code),
  kind           text not null,
  description_id text not null,
  constraint chk_license_kind check (kind in ('WAJIB', 'PROFESI', 'TAMBAHAN'))
);

comment on column public.licenses.kind is
  'WAJIB = syarat hukum untuk boleh bekerja; PROFESI = sertifikat kompetensi yang lazim diminta pemberi kerja; TAMBAHAN = menambah nilai.';

alter table public.licenses enable row level security;
drop policy if exists licenses_read_all on public.licenses;
create policy licenses_read_all on public.licenses
  for select to anon, authenticated using (true);

create table if not exists public.career_licenses (
  career_id     integer  not null references public.careers(id) on delete cascade,
  license_code  text     not null references public.licenses(code) on delete cascade,
  display_order smallint not null,
  primary key (career_id, license_code)
);

create index if not exists idx_career_licenses_career
  on public.career_licenses (career_id, display_order);

alter table public.career_licenses enable row level security;
drop policy if exists career_licenses_read_all on public.career_licenses;
create policy career_licenses_read_all on public.career_licenses
  for select to anon, authenticated using (true);

