  ('DATA_CERT', 'Sertifikasi Analitik Data (Google / Microsoft)', 'VENDOR', 'TAMBAHAN', 'Bukti kemampuan mengolah dan memvisualkan data untuk keputusan bisnis.'),
  ('DIGITAL_MKT', 'Sertifikasi Pemasaran Digital (Google / Meta)', 'VENDOR', 'TAMBAHAN', 'Bukti kemampuan menjalankan dan mengukur kampanye digital.'),
  ('HACCP', 'Sertifikasi HACCP / Keamanan Pangan', 'BNSP', 'PROFESI', 'Sistem analisis bahaya dan titik kendali kritis pada produksi pangan.'),
  ('HIGIENE', 'Sertifikat Higiene Sanitasi Pangan', 'KEMENKES', 'WAJIB', 'Wajib bagi penjamah makanan di jasa boga dan restoran.'),
  ('IP_PII', 'Sertifikat Insinyur Profesional (IP)', 'PII', 'PROFESI', 'Pengakuan profesi insinyur setelah Program Profesi Insinyur dan pengalaman kerja.'),
  ('K3_KONS', 'Sertifikat K3 Konstruksi', 'KEMNAKER', 'PROFESI', 'Keselamatan kerja khusus lingkungan proyek konstruksi.'),
  ('K3_UMUM', 'Sertifikat Ahli K3 Umum', 'KEMNAKER', 'PROFESI', 'Kompetensi keselamatan dan kesehatan kerja yang diakui Kemnaker.'),
  ('KAMAR_BEDAH', 'Pelatihan Perawat Kamar Bedah', 'ORG_KES', 'TAMBAHAN', 'Pelatihan kekhususan teknik aseptik, instrumentasi, dan alur kerja kamar operasi.'),
  ('LAS', 'Sertifikat Juru Las (Welder)', 'KEMNAKER', 'PROFESI', 'Kompetensi pengelasan sesuai posisi dan jenis material.'),
  ('LISTRIK', 'Sertifikat Kompetensi Ketenagalistrikan', 'KEMNAKER', 'WAJIB', 'Wajib bagi tenaga teknik yang bekerja pada instalasi tenaga listrik.'),
  ('MSIB', 'Sertifikat Magang Bersertifikat', 'KEMNAKER', 'TAMBAHAN', 'Bukti pengalaman magang terstruktur yang diakui industri.'),
  ('NIDN', 'NIDN (Nomor Induk Dosen Nasional)', 'KEMDIKBUD', 'WAJIB', 'Nomor registrasi dosen tetap perguruan tinggi.'),
  ('NUPTK', 'NUPTK (Nomor Unik Pendidik dan Tenaga Kependidikan)', 'KEMDIKBUD', 'PROFESI', 'Nomor identitas pendidik yang dipakai untuk administrasi dan tunjangan.'),
  ('OPERATOR', 'SIO (Surat Izin Operator) Alat Berat', 'KEMNAKER', 'WAJIB', 'Izin mengoperasikan pesawat angkat-angkut dan alat berat di tempat kerja.'),
  ('PARIWISATA', 'Sertifikat Kompetensi Pariwisata', 'KEMENPAREKRAF', 'PROFESI', 'Skema kompetensi bidang perhotelan, kuliner, dan perjalanan wisata.'),
  ('PMP', 'Sertifikasi Manajemen Proyek (PMP / CAPM)', 'VENDOR', 'TAMBAHAN', 'Standar internasional pengelolaan proyek.'),
  ('PPI', 'Pelatihan PPI (Pencegahan dan Pengendalian Infeksi)', 'ORG_KES', 'PROFESI', 'Standar kewaspadaan infeksi di fasilitas kesehatan.'),
  ('PROTEKSI_RAD', 'Surat Izin Bekerja Petugas Proteksi Radiasi', 'BAPETEN', 'WAJIB', 'Izin bekerja di lingkungan radiasi pengion, wajib bagi radiografer dan sejenisnya.'),
  ('SCRUM', 'Sertifikasi Scrum (PSM / CSM)', 'VENDOR', 'TAMBAHAN', 'Kompetensi menjalankan proses pengembangan produk secara agile.'),
  ('SERDIK', 'Sertifikat Pendidik (melalui PPG)', 'KEMDIKBUD', 'WAJIB', 'Syarat menjadi guru profesional, diperoleh lewat Pendidikan Profesi Guru.'),
  ('SIM_B', 'SIM B I / B II Umum', 'POLRI', 'WAJIB', 'Izin mengemudi kendaraan barang atau penumpang berukuran besar.'),
  ('SIP', 'SIP (Surat Izin Praktik)', 'DINKES', 'WAJIB', 'Izin praktik di satu fasilitas kesehatan tertentu, diterbitkan daerah setelah STR terbit.'),
  ('SIPA', 'SIPA (Surat Izin Praktik Apoteker)', 'DINKES', 'WAJIB', 'Izin praktik apoteker di apotek, rumah sakit, atau industri farmasi.'),
  ('SIPB', 'SIPB (Surat Izin Praktik Bidan)', 'DINKES', 'WAJIB', 'Izin praktik khusus bidan, diterbitkan Dinas Kesehatan daerah tempat bekerja.'),
  ('SIPD', 'SIP Dokter', 'DINKES', 'WAJIB', 'Izin praktik dokter, diterbitkan setelah STR dan rekomendasi organisasi profesi.'),
  ('SIPP', 'SIPP (Surat Izin Praktik Perawat)', 'DINKES', 'WAJIB', 'Izin praktik khusus perawat, diterbitkan Dinas Kesehatan daerah tempat bekerja.'),
  ('SKA_ARS', 'STRA / Lisensi Arsitek', 'IAPI_ARS', 'WAJIB', 'Registrasi arsitek yang diwajibkan UU Arsitek untuk menandatangani dokumen perencanaan.'),
  ('SKK', 'SKK Konstruksi (Sertifikat Kompetensi Kerja)', 'LPJK', 'WAJIB', 'Wajib bagi tenaga kerja konstruksi sesuai jenjang jabatan di proyek.'),
  ('SPBE', 'Sertifikasi Keamanan Informasi', 'KOMDIGI', 'TAMBAHAN', 'Kompetensi pengelolaan keamanan sistem elektronik.'),
  ('STR', 'STR (Surat Tanda Registrasi) Aktif', 'KTKI', 'WAJIB', 'Bukti bahwa kompetensi tenaga kesehatan diakui negara. Wajib aktif sebelum boleh melayani pasien.'),
  ('STRI', 'STRI (Surat Tanda Registrasi Insinyur)', 'PII', 'WAJIB', 'Registrasi insinyur yang diwajibkan UU Keinsinyuran untuk praktik keinsinyuran.'),
