-- ---------------------------------------------------------------------------
-- 4. Tampilan siap pakai
-- ---------------------------------------------------------------------------
create or replace view public.career_tool_view
with (security_invoker = true) as
select ct.career_id,
       t.code        as tool_code,
       t.name_id     as nama,
       t.description_id as deskripsi,
       ct.contoh_produk,
       p.code        as fase_code,
       p.name_id     as fase,
       p.subtitle    as fase_subtitle,
       p.sort_order  as fase_order,
       ct.display_order
from public.career_tools ct
join public.tools t       on t.code = ct.tool_code
join public.tool_phases p on p.code = t.phase_code;

create or replace view public.career_license_view
with (security_invoker = true) as
select cl.career_id,
       l.code    as license_code,
       l.name_id as nama,
       i.name_id as penerbit,
       l.kind    as sifat,
       l.description_id as deskripsi,
       cl.display_order
from public.career_licenses cl
join public.licenses l        on l.code = cl.license_code
join public.license_issuers i on i.code = l.issuer_code;

-- ---------------------------------------------------------------------------
-- 5. Penjaga
-- ---------------------------------------------------------------------------
do $$
declare v_t int; v_l int; v_f int;
begin
  select count(*) into v_t
  from public.careers c where c.is_active
    and not exists (select 1 from public.career_tools x where x.career_id = c.id);
  if v_t > 0 then
    raise exception '0028: % profesi aktif tanpa tools', v_t;
  end if;

  select count(*) into v_f
  from public.careers c where c.is_active
    and not exists (
      select 1 from public.career_tools ct
      join public.tools t on t.code = ct.tool_code
      where ct.career_id = c.id and t.phase_code = 'MANDIRI');
  if v_f > 0 then
    raise exception '0028: % profesi tanpa tools fase MANDIRI', v_f;
  end if;

  select count(*) into v_l
  from public.careers c where c.is_active
    and (select count(*) from public.career_licenses x where x.career_id = c.id) < 3;
  if v_l > 0 then
    raise exception '0028: % profesi punya kurang dari 3 lisensi', v_l;
  end if;

  raise notice '0028: % tools, % tautan tools, % lisensi, % tautan lisensi',
    (select count(*) from public.tools),
    (select count(*) from public.career_tools),
    (select count(*) from public.licenses),
    (select count(*) from public.career_licenses);
end $$;

commit;
